def climato(T, Pr, title="", w=86, pmax=300, tmax=30, foot=True):
    """Climatogramme : barres = précipitations (mm, axe de gauche) ; courbe = températures (°C, axe de droite) ; 1 °C = 10 mm."""
    x0, x1, y0, y1 = 36, 228, 172, 24
    bw = (x1 - x0) / 12
    Yp = lambda v: y0 - v / pmax * (y0 - y1)
    Yt = lambda v: y0 - v / tmax * (y0 - y1)
    o = [f'<text x="132" y="12" font-size="11" font-weight="700" text-anchor="middle">{title}</text>']
    for v in range(0, pmax + 1, 50):
        o.append(f'<line x1="{x0}" y1="{Yp(v):.1f}" x2="{x1}" y2="{Yp(v):.1f}" stroke="#e3e6ec"/><text x="{x0 - 4}" y="{Yp(v) + 3:.1f}" font-size="8" text-anchor="end" fill="#2563c9">{v}</text>'
                 f'<text x="{x1 + 4}" y="{Yp(v) + 3:.1f}" font-size="8" fill="#C0392B">{v * tmax // pmax}</text>')
    for i, p in enumerate(Pr):
        o.append(f'<rect x="{x0 + i * bw + 2:.1f}" y="{Yp(p):.1f}" width="{bw - 4:.1f}" height="{y0 - Yp(p):.1f}" fill="#6FB1EA"/>')
        o.append(f'<text x="{x0 + (i + .5) * bw:.1f}" y="{y0 + 11}" font-size="8.5" text-anchor="middle">{MOIS[i]}</text>')
    pts = " ".join(f"{x0 + (i + .5) * bw:.1f},{Yt(t):.1f}" for i, t in enumerate(T))
    o.append(f'<polyline points="{pts}" fill="none" stroke="#E4572E" stroke-width="2.4"/>' + "".join(f'<circle cx="{x0 + (i + .5) * bw:.1f}" cy="{Yt(t):.1f}" r="2.4" fill="#E4572E"/>' for i, t in enumerate(T)))
    o.append(f'<line x1="{x0}" y1="{y1 - 4}" x2="{x0}" y2="{y0}" stroke="#1F2A44" stroke-width="1.3"/><line x1="{x1}" y1="{y1 - 4}" x2="{x1}" y2="{y0}" stroke="#1F2A44" stroke-width="1.3"/><line x1="{x0}" y1="{y0}" x2="{x1}" y2="{y0}" stroke="#1F2A44" stroke-width="1.3"/>')
    o.append(f'<text x="{x0 - 4}" y="{y1 - 9}" font-size="8.5" fill="#2563c9" text-anchor="end" font-weight="700">mm</text><text x="{x1 + 4}" y="{y1 - 9}" font-size="8.5" fill="#C0392B" font-weight="700">°C</text>')
    if foot:
        moy = str(round(sum(T) / 12, 1)).replace(".", ",")
        o.append(f'<text x="132" y="{y0 + 26}" font-size="8.5" text-anchor="middle">Moyenne annuelle : {moy} °C · Total des précipitations : {sum(Pr)} mm</text>')
    return f'<svg viewBox="0 0 264 {y0 + 32}" width="{w}mm" style="max-width:100%;height:auto" font-family="Poppins,DejaVu Sans" fill="#1F2A44">{"".join(o)}</svg>'


