def relief(w="100%", quiz=False):
    """Carte simplifiée du relief de la Belgique (trois grandes zones d'altitude)."""
    W, H = P(6.6, 49.4)
    mid = [(2.3, 50.72), (3.3, 50.74), (4.0, 50.80), (4.6, 50.84), (5.2, 50.86), (5.6, 50.88), (6.6, 50.92), (6.6, 49.3), (2.3, 49.3)]
    high = [(2.3, 50.25), (3.7, 50.26), (4.15, 50.30), (4.44, 50.41), (4.87, 50.47), (5.24, 50.52), (5.57, 50.60), (5.85, 50.70), (6.6, 50.80), (6.6, 49.3), (2.3, 49.3)]
    o = [f'<defs><clipPath id="be"><polygon points="{poly(BEL)}"/></clipPath></defs>',
         f'<g clip-path="url(#be)"><polygon points="{poly(BEL)}" fill="#CFEAB8"/><polygon points="{poly(mid)}" fill="#F3E3A2"/><polygon points="{poly(high)}" fill="#DDA56A"/></g>',
         f'<polygon points="{poly(BEL)}" fill="none" stroke="#1F2A44" stroke-width="1.6"/>']
    for riv in (MEUSE, SAMBRE, ESCAUT):
        o.append(f'<polyline points="{poly(riv)}" fill="none" stroke="#3A86FF" stroke-width="2" stroke-linecap="round"/>')
    for nm, lo, la, dx in [("Bruxelles", 4.35, 50.85, 6), ("Anvers", 4.40, 51.22, 6), ("Gand", 3.72, 51.05, 6), ("Namur", 4.87, 50.47, 6), ("Liège", 5.57, 50.63, -30), ("Arlon", 5.82, 49.68, -32), ("Ostende", 2.92, 51.22, 5)]:
        x, y = P(lo, la)
        o.append(f'<circle cx="{x:.0f}" cy="{y:.0f}" r="3.3" fill="#1F2A44"/>' + ("" if quiz else f'<text x="{x + dx:.0f}" y="{y + 4:.0f}" font-size="9.5" font-weight="700">{nm}</text>'))
    tx, ty = P(6.09, 50.50)
    o.append(f'<path d="M{tx:.0f} {ty - 6:.0f} l5 9 h-10z" fill="#6B4A2B"/>' + ("" if quiz else f'<text x="{tx - 64:.0f}" y="{ty + 15:.0f}" font-size="8.5">Botrange 694 m</text>'))
    for k, (lo, la) in enumerate([(3.6, 51.05), (4.2, 50.58), (5.2, 50.05)]):
        x, y = P(lo, la)
        o.append(f'<circle cx="{x:.0f}" cy="{y:.0f}" r="9" fill="#fff" stroke="#1F2A44" stroke-width="1.4"/><text x="{x:.0f}" y="{y + 4:.0f}" font-size="11" font-weight="800" text-anchor="middle">{"ABC"[k]}</text>')
    sx, sy = P(2.6, 49.75)
    Lk = 50 / 111 * 150
    o.append(f'<rect x="{sx:.0f}" y="{sy:.0f}" width="{Lk:.0f}" height="5" fill="#1F2A44"/><rect x="{sx + Lk / 2:.0f}" y="{sy:.0f}" width="{Lk / 2:.0f}" height="5" fill="#fff" stroke="#1F2A44"/><text x="{sx:.0f}" y="{sy + 16:.0f}" font-size="9">0</text><text x="{sx + Lk - 14:.0f}" y="{sy + 16:.0f}" font-size="9">50 km</text>')
    nx, ny = P(2.75, 51.5)
    o.append(f'<path d="M{nx:.0f} {ny + 18:.0f} L{nx:.0f} {ny - 6:.0f} M{nx - 6:.0f} {ny + 2:.0f} L{nx:.0f} {ny - 8:.0f} L{nx + 6:.0f} {ny + 2:.0f}" stroke="#1F2A44" stroke-width="2" fill="none"/><text x="{nx - 4:.0f}" y="{ny - 11:.0f}" font-size="11" font-weight="800">N</text>')
    for nm, lo, la in [("MER DU NORD", 2.6, 51.45), ("PAYS-BAS", 4.6, 51.56), ("ALLEMAGNE", 6.0, 51.0), ("FRANCE", 3.0, 50.1), ("LUX.", 6.05, 49.75)]:
        x, y = P(lo, la)
        o.append(f'<text x="{x:.0f}" y="{y:.0f}" font-size="8.5" fill="#7a8193" letter-spacing="1">{nm}</text>')
    svg = f'<svg viewBox="0 0 {W:.0f} {H:.0f}" width="{w}" font-family="Poppins" fill="#1F2A44">{"".join(o)}</svg>'
    leg = "".join(f'<div class="flex xs" style="gap:2mm;margin-bottom:1.2mm"><span style="display:inline-block;width:6mm;height:4mm;{st}"></span>{t}</div>' for st, t in [
        ("background:#CFEAB8;border:1px solid #aaa", "moins de 100 m"), ("background:#F3E3A2;border:1px solid #aaa", "de 100 à 200 m"), ("background:#DDA56A;border:1px solid #aaa", "plus de 200 m"),
        ("border-top:2.5px solid #3A86FF;height:0", "fleuve, rivière"), ("background:#1F2A44;border-radius:50%;width:3mm;height:3mm", "ville"), ("", "▲ point culminant")])
    return f'<div class="grid2" style="grid-template-columns:2.3fr 1fr;align-items:center;gap:3mm">{svg}<div class="card" style="padding:2mm"><b class="sm">Le relief de la Belgique</b><div class="xs muted mb2">(carte simplifiée)</div>{leg}</div></div>'


def camembert(parts, title, w=58):
    """Diagramme circulaire : parts = [(étiquette, %, couleur), …]."""
    import math
    o, a = [], -math.pi / 2
    for lab, pc, col in parts:
        b = a + 2 * math.pi * pc / 100
        large = 1 if pc > 50 else 0
        x1, y1, x2, y2 = 70 + 60 * math.cos(a), 75 + 60 * math.sin(a), 70 + 60 * math.cos(b), 75 + 60 * math.sin(b)
        o.append(f'<path d="M70 75 L{x1:.1f} {y1:.1f} A60 60 0 {large} 1 {x2:.1f} {y2:.1f}Z" fill="{col}" stroke="#fff" stroke-width="1.5"/>')
        a = b
    leg = "".join(f'<rect x="140" y="{40 + i * 22}" width="11" height="11" fill="{c}"/><text x="156" y="{50 + i * 22}" font-size="10">{l} : {p} %</text>' for i, (l, p, c) in enumerate(parts))
    return f'<svg viewBox="0 0 280 150" width="{w * 1.6:.0f}mm" style="max-width:100%;height:auto" font-family="Poppins" fill="#1F2A44"><text x="140" y="11" font-size="10.5" font-weight="700" text-anchor="middle">{title}</text>{"".join(o)}{leg}</svg>'


def profil(w=176):
    """Profil d'altitude d'une promenade (12 km)."""
    pts = [(0, 180), (1, 210), (2, 290), (3, 350), (4, 380), (5, 320), (6, 240), (7, 200), (8, 260), (9, 340), (10, 300), (11, 220), (12, 180)]
    X = lambda k: 44 + k * 44
    Y = lambda a: 170 - (a - 150) * 0.56
    o = ["".join(f'<line x1="44" y1="{Y(v):.0f}" x2="572" y2="{Y(v):.0f}" stroke="#e3e6ec"/><text x="38" y="{Y(v) + 3:.0f}" font-size="9" text-anchor="end">{v}</text>' for v in range(150, 401, 50))]
    o.append("".join(f'<text x="{X(k)}" y="184" font-size="9" text-anchor="middle">{k}</text>' for k in range(13)))
    d = " ".join(f"{X(k):.0f},{Y(a):.0f}" for k, a in pts)
    o.append(f'<polygon points="44,170 {d} 572,170" fill="#CFE8C4"/><polyline points="{d}" fill="none" stroke="{MC}" stroke-width="2.5"/>')
    for k, a, t in [(0, 180, "Départ : gare"), (4, 380, "Rocher du Faucon"), (7, 200, "Moulin"), (9, 340, "Tour de vue")]:
        o.append(f'<circle cx="{X(k)}" cy="{Y(a):.0f}" r="4" fill="#E4572E"/><text x="{X(k) + (6 if k == 0 else 0)}" y="{Y(a) - 8:.0f}" font-size="9.5" font-weight="700" text-anchor="{"start" if k == 0 else "middle"}">{t}</text>')
    o.append('<text x="308" y="198" font-size="9.5" text-anchor="middle">distance (km)</text><text x="10" y="100" font-size="9.5" transform="rotate(-90 10 100)" text-anchor="middle">altitude (m)</text>')
    return f'<svg viewBox="0 0 590 202" width="{w}mm" style="max-width:100%;height:auto" font-family="Poppins" fill="#1F2A44">{"".join(o)}</svg>'


def build_v3m5(start=1, tstart=1, render=True):
    b = Book("V3 · M5", "Volume 3 · Je réussis à l'école · Module 5 · Lire le monde", MC, start=start)
    E = Ex(b)
    vis = ('<div class="flex" style="justify-content:space-around;align-items:flex-end">' + avatar("prof", 80, "sourire") + '<div style="font-size:36pt">🗺️ 🧭</div>' + avatar("yonas", 80, "pense") + '<div style="font-size:36pt">⛰️ 🌧️</div>'
           + avatar("fatou", 80, "sourire") + '<div style="font-size:36pt">🌍 🏙️</div>' + avatar("mateo", 80, "surpris") + '</div>')
    opening(b, MC, 5, "Lire le monde", vis, [("🏞️", "décrire un paysage (les plans, les éléments naturels et humains)"), ("🗺️", "lire une carte : titre, légende, échelle, orientation"), ("⚖️", "comparer des lieux (plus… que, autant de…, deux fois plus…)"),
            ("➗", "exprimer une proportion (la moitié, un quart, 30 %, la plupart…)"), ("🌦️", "lire et comparer des climatogrammes"), ("🌍", "présenter le dossier d'un pays")],
            ["Décris un paysage de ton pays que tu aimes : montagne, désert, mer, ville… ?", "Quel temps fait-il chez toi en janvier ? Et en juillet ?", "Ton pays est-il plus grand ou plus petit que la Belgique ? Plus peuplé ?"],
            ["un paysage", "le relief", "le climat", "une carte", "la légende", "l'échelle", "la population", "la densité", "un climatogramme", "la moitié", "deux fois plus"], TINT)

    # ---------- Découvrir ----------
    bd = '<div class="grid2" style="gap:3mm">' + "".join([
        bd_case(1, lr("mateo", ["Madame, on va où pour la classe de dépaysement ?"], "prof", ["Dans les Hautes Fagnes, près d'Eupen et de Malmedy. C'est le plateau le plus élevé de Belgique."], "pense", "sourire")),
        bd_case(2, lr("yonas", ["Le plus élevé ? Il fait combien de mètres ? En Érythrée, Asmara est à plus de 2 300 mètres !"], "prof", ["Le point culminant, le signal de Botrange, est à 694 mètres. Asmara est donc plus de trois fois plus haute !"], "surpris", "rire")),
        bd_case(3, lr("daria", ["Il faut prendre quels vêtements ? Il fait froid, là-bas ?"], "prof", ["Plus froid qu'à Bruxelles, et il pleut davantage. En hiver, il y a souvent de la neige. Prenez des bottes et un imperméable !"], "pense", "sourire")),
        bd_case(4, lr("bilal", ["Qu'est-ce qu'on va voir ? Des forêts ?"], "educ", ["Des forêts, oui, mais surtout des fagnes : des marais où le sol est gorgé d'eau. On marche sur des caillebotis, des chemins en planches."], "pense", "sourire")),
        bd_case(5, lr("amina", ["Moi, je préfère la mer ! À la côte, tout est plat."], "prof", ["C'est vrai : la plaine maritime est presque au niveau de la mer. La Belgique est petite, mais ses paysages sont très variés."], "rire", "sourire")),
        bd_case(6, lr("fatou", ["En Guinée, il y a la saison des pluies et la saison sèche. Ici, il pleut toute l'année !"], "prof", ["Bonne remarque : ce sont deux climats différents. À la fin du module, chacun présentera le dossier d'un pays."], "sourire", "rire")),
    ]) + '</div>'
    e = E("J'écoute et je lis la BD : la classe de dépaysement.", bd, ["ecoute", "lis"], 1, "A",
          script="Lire deux fois. Demander : « Où la classe va-t-elle partir ? Qu'est-ce qu'un plateau ? Quelle est l'altitude du signal de Botrange ? Comparez avec Asmara. Pourquoi faut-il prendre des bottes ? Qu'est-ce qu'une fagne ? Qu'est-ce qui différencie le climat de la Guinée et celui de la Belgique ? » Signaler le belgicisme « classe de dépaysement » (classe verte, classe de neige, classe de mer).", sol="Activité orale.")
    b.page(f'<h2>Découvrir · La classe de dépaysement</h2>{e}', "Découvrir")
    e = E("Je réponds par une phrase complète.", f'<p>1. Où se trouvent les Hautes Fagnes ? {blank("xl")}</p><p>2. Quel est le point culminant de la Belgique ? Quelle est son altitude ? {blank("xl")}</p><p>3. Pourquoi faut-il prendre des bottes et un imperméable ? {blank("xl")}</p><p>4. Comment marche-t-on dans les fagnes ? Pourquoi ? {blank("xl")}</p><p>5. Quelle différence Fatou remarque-t-elle entre la Guinée et la Belgique ? {blank("xl")}</p>', ["lis", "ecris"], 1, "B",
          sol="1. Près d'Eupen et de Malmedy (est du pays). — 2. Le signal de Botrange, 694 m. — 3. Il fait plus froid, il pleut davantage, il neige souvent en hiver. — 4. Sur des caillebotis : le sol est gorgé d'eau. — 5. Guinée : saison des pluies et saison sèche ; Belgique : pluie toute l'année.")
    e2 = E("Vrai ou faux ? Je coche et je corrige les phrases fausses.", vf(["Les Hautes Fagnes sont une plaine au bord de la mer.", "Asmara est plus haute que le signal de Botrange.", "Une fagne est un marais.", "La plaine maritime est très élevée."]), ["lis", "coche"], 1, "B",
           sol="Faux (c'est un plateau, le plus élevé de Belgique) · Vrai · Vrai · Faux (elle est presque au niveau de la mer)")
    e3 = E("Les mots de la BD. Je trouve le mot qui veut dire…", '<p>1. le point le plus haut d\'un pays : le point ______________ 2. une étendue plate et élevée : un ______________ 3. un terrain très humide, plein d\'eau : un ______________ 4. un chemin fait de planches : un ______________ 5. un séjour scolaire hors de l\'école (belgicisme) : une classe de ______________</p>', ["lis", "ecris"], 1, "B",
           sol="1. culminant — 2. plateau — 3. marais (une fagne) — 4. caillebotis — 5. dépaysement")
    e4 = E("Et toi ? Décris en 3 phrases un paysage de ton pays : où est-il ? Comment est-il ? Quel temps y fait-il ?", lines(3), ["ecris"], 2, "C",
           sol="Production personnelle. Ex. : En Syrie, près de Lattaquié, il y a des montagnes couvertes de forêts. On voit la mer au loin. En été, il fait très chaud et il ne pleut presque pas.")
    b.page(f'{e}{e2}{e3}{e4}', "Découvrir")
    txt = f'''<div class="card" style="{SERIF};background:#F3FAFA;font-size:10.2pt"><p style="margin-bottom:1mm"><b>« La Belgique, un petit pays aux paysages variés »</b> <span class="xs muted">(texte documentaire écrit pour la classe)</span></p>
<p>Avec environ 30 700 km², la Belgique est un petit pays : la République démocratique du Congo est plus de 75 fois plus grande. Pourtant, en quelques heures de train, on traverse des paysages très différents. Du nord-ouest au sud-est, l'altitude augmente progressivement.</p>
<p>Au nord, la <b>Basse Belgique</b> (moins de 100 m) est une région plate. Le long de la mer du Nord, sur 67 km, s'étendent des plages et des dunes. Derrière elles, les polders sont des terres gagnées sur la mer, protégées par des digues. La Basse Belgique est très peuplée : les villes y sont nombreuses et proches les unes des autres.</p>
<p>Au centre, la <b>Moyenne Belgique</b> (de 100 à 200 m) est formée de plateaux couverts de limon, une terre très fertile. En Hesbaye, la plupart des terres sont cultivées : on y produit des céréales et des betteraves sucrières.</p>
<p>Au sud du sillon formé par la Sambre et la Meuse commence la <b>Haute Belgique</b> (plus de 200 m). L'Ardenne est un vieux plateau entaillé par des vallées profondes, où serpentent des rivières comme la Semois, l'Ourthe ou la Lesse. Les forêts y couvrent de grandes surfaces. Le climat y est plus froid et plus humide qu'au nord, et la population y est beaucoup moins dense.</p></div>'''
    p_txt = b.n + 1
    e = E("Je lis le texte documentaire. Je réponds.", txt + f'<p class="mt2">1. Comment l\'altitude change-t-elle du nord-ouest au sud-est ? {blank("xl")}</p><p>2. Qu\'est-ce qu\'un polder ? {blank("xl")}</p><p>3. Pourquoi cultive-t-on beaucoup en Hesbaye ? {blank("xl")}</p><p>4. Cite deux caractéristiques de l\'Ardenne. {blank("xl")}</p><p>5. Où la population est-elle la plus dense ? la moins dense ? {blank("xl")}</p>', ["lis", "ecris"], 2, "B",
          sol="1. Elle augmente progressivement (Basse, Moyenne, Haute Belgique). — 2. Une terre gagnée sur la mer, protégée par des digues. — 3. Le limon est très fertile. — 4. Ex. : vieux plateau, vallées profondes, forêts, climat plus froid. — 5. Plus dense en Basse Belgique ; moins dense en Ardenne.")
    e2 = E("Les mots du texte. Je relie le mot et sa définition.", relie(["le limon", "une digue", "fertile", "serpenter", "le sillon Sambre-Meuse"], ["un mur de terre qui protège de la mer", "faire de nombreuses courbes", "la longue vallée formée par deux rivières", "une terre fine déposée par l'eau ou le vent", "où les plantes poussent bien"]), ["lis", "relie"], 1, "B",
           sol="limon → terre fine déposée · digue → mur qui protège de la mer · fertile → où les plantes poussent bien · serpenter → faire de nombreuses courbes · sillon Sambre-Meuse → longue vallée formée par deux rivières")
    b.page(f'<h2>Découvrir · Des paysages variés</h2>{e}{e2}', "Découvrir")

    # ---------- Lexique ----------
    e = E("Les formes du relief. J'écoute et je répète.", coupe(True), ["ecoute", "repete"], 1, "A",
          script="Montrer chaque forme de gauche à droite. Expliquer : plaine = étendue plate et basse ; colline = petite hauteur aux pentes douces ; plateau = étendue plate et élevée ; vallée = creux entre deux hauteurs, souvent avec une rivière ; montagne = grande hauteur, pentes raides, sommet (parfois enneigé). Demander quelles formes existent en Belgique.", sol="Activité orale.")
    e2 = E("Je relie la forme du relief et sa définition.", relie(["une plaine", "une colline", "un plateau", "une vallée", "une montagne"], ["un creux allongé entre deux hauteurs", "une grande hauteur aux pentes raides", "une étendue plate et basse", "une étendue plate et élevée", "une petite hauteur aux pentes douces"]), ["relie"], 1, "B",
           sol="plaine → plate et basse · colline → petite hauteur aux pentes douces · plateau → plate et élevée · vallée → creux allongé · montagne → grande hauteur aux pentes raides")
    e3 = E("Je complète avec : le sommet · l'altitude · le versant · la source · l'embouchure.", '<div class="card" style="line-height:2">1. La hauteur d\'un lieu par rapport au niveau de la mer, c\'est ______________ . 2. Le point le plus haut d\'une montagne, c\'est ______________ . 3. Le côté d\'une montagne ou d\'une vallée, c\'est ______________ . 4. L\'endroit où naît une rivière, c\'est ______________ . 5. L\'endroit où un fleuve se jette dans la mer, c\'est ______________ .</div>', ["complete"], 1, "C",
           sol="1. l'altitude — 2. le sommet — 3. le versant — 4. la source — 5. l'embouchure")
    e4 = E("Quelles formes de relief trouve-t-on en Belgique ? Et dans ton pays ? J'écris 2 phrases.", lines(2), ["ecris"], 2, "C", sol="Ex. : En Belgique, il y a une plaine au nord, des plateaux au centre et au sud, des collines et des vallées, mais pas de vraie montagne. En Afghanistan, il y a de très hautes montagnes.")
    b.page(f'<h2>Les mots du relief</h2>{e}{e2}{e3}{e4}', "Lexique")
    mots = [("☀️", "l'ensoleillement"), ("🌧️", "les précipitations"), ("❄️", "la neige, le gel"), ("💨", "le vent"), ("🌫️", "le brouillard"), ("⛈️", "un orage"), ("🔥", "une canicule"), ("🏜️", "une sécheresse"), ("🌊", "une inondation"), ("🌡️", "la température"), ("☔", "la saison des pluies"), ("🌵", "la saison sèche")]
    e = E("Les mots du temps et du climat. J'écoute et je répète.", emogrid(mots, 6, False).replace('font-size:10pt', 'font-size:9pt'), ["ecoute", "repete"], 1, "A",
          script="Nommer chaque mot. Distinguer : le temps (la météo) = ce qu'il fait aujourd'hui ; le climat = le temps moyen d'une région, observé pendant au moins 30 ans.", sol="Activité orale.")
    e2 = E("Le temps ou le climat ? J'écris T (temps) ou C (climat).", '<div class="card" style="line-height:1.7">___ Demain, il pleuvra sur l\'Ardenne. &nbsp; ___ En Belgique, les hivers sont doux et les étés sont frais.<br>___ À Kinshasa, il y a une saison sèche de juin à septembre. &nbsp; ___ Ce matin, il y a du brouillard à Namur.<br>___ Au Sahara, il pleut très peu toute l\'année. &nbsp; ___ Cet après-midi, un orage est possible.</div>', ["lis", "ecris"], 1, "B",
           sol="T · C · C · T · C · T")
    e3 = E("J'écoute le bulletin météo de la radio. Je complète le tableau.", table(["", "Ciel", "Température maximale"], [["Ostende (la côte)", "", ""], ["Bruxelles", "", ""], ["Liège", "", ""], ["Saint-Hubert (l'Ardenne)", "", ""]], ["56mm", "70mm", "56mm"]).replace("<td></td>", '<td style="height:6.5mm"></td>'), ["ecoute", "ecris"], 2, "A",
           script="« Voici la météo pour ce mardi. À la côte, à Ostende, le soleil brille, mais le vent souffle fort ; il fera 9 degrés. À Bruxelles, le ciel sera nuageux avec quelques averses et 8 degrés. À Liège, des pluies toute la journée et 7 degrés. En Ardenne, à Saint-Hubert, il fera plus froid : 3 degrés, et la pluie se transformera en neige en fin de journée. »",
           sol="Ostende : soleil, vent fort, 9 °C · Bruxelles : nuageux, averses, 8 °C · Liège : pluie toute la journée, 7 °C · Saint-Hubert : pluie puis neige, 3 °C")
    e4 = E("Les mots de la météo en Belgique. Je relie l'expression belge et son sens.", relie(["« Il drache ! »", "« la drache nationale »", "« Il fait cru. »", "« Il fait douf. »"], ["il fait froid et humide", "il pleut très fort", "il fait lourd, chaud et humide", "la pluie (souvent) du 21 juillet, jour de la fête nationale"]), ["lis", "relie"], 1, "B",
           sol="il drache → il pleut très fort · drache nationale → la pluie du 21 juillet (plaisanterie belge) · il fait cru → froid et humide · il fait douf → lourd, chaud et humide (belgicismes familiers)")
    b.page(f'<h2>Les mots du temps et du climat</h2>{e}{e2}{e3}{e4}', "Lexique")
    e = E("Les mots de la population. Je lis l'encadré.", '<div class="grid2"><div class="card" style="background:#fff"><b>👥 Compter les habitants</b><p class="sm" style="margin:1mm 0 0">la <b>population</b> = tous les habitants d\'un lieu<br>un pays <b>peuplé</b> ≠ un pays <b>peu peuplé</b> (presque désert)<br>la <b>densité</b> = le nombre moyen d\'habitants par km²<br><b>densité = population ÷ superficie</b><br><i>Belgique : 11 825 551 hab. ÷ 30 689 km² ≈ 385 hab./km²</i></p></div>'
          '<div class="card" style="background:#fff"><b>🏙️ Ville et campagne</b><p class="sm" style="margin:1mm 0 0">la ville → <b>urbain</b> · la campagne → <b>rural</b><br>une <b>agglomération</b> = une ville et ses banlieues<br>l\'<b>exode rural</b> = le départ des habitants de la campagne vers la ville<br>la <b>migration</b> = le déplacement d\'une population<br>Aujourd\'hui, plus de la moitié des humains vivent en ville.</p></div></div>', ["lis"], 1, "B", sol="Lecture guidée.")
    e2 = E("Urbain ou rural ? Je classe : un immeuble · une ferme · un embouteillage · un champ de blé · le métro · un tracteur · une gare centrale · un petit village.", table(["🏙️ urbain", "🌾 rural"], [["", ""]], ["91mm", "91mm"]).replace("<td></td>", '<td style="height:11mm"></td>'), ["lis", "ecris"], 1, "C",
           sol="Urbain : un immeuble, un embouteillage, le métro, une gare centrale — Rural : une ferme, un champ de blé, un tracteur, un petit village")
    e3 = E("Du nom à l'adjectif. Je complète.", '<p>1. la montagne → une région ______________ 2. la côte → une ville ______________ 3. le climat → un changement ______________ 4. le désert → une zone ______________ 5. la mer → un climat ______________ 6. l\'Europe → un pays ______________</p>', ["ecris"], 2, "C",
           sol="1. montagneuse — 2. côtière — 3. climatique — 4. désertique — 5. maritime (océanique) — 6. européen")
    e4 = E("Les noms des pays et des habitants. Je complète le tableau.", table(["Pays", "Habitant(e)", "Pays", "Habitant(e)"], [["la Belgique", "un(e) Belge", "la Syrie", ""], ["le Congo (RDC)", "", "l'Ukraine", ""], ["l'Érythrée", "", "l'Afghanistan", ""], ["la Guinée", "", "le Maroc", ""]], ["44mm", "47mm", "44mm", "47mm"]), ["ecris"], 2, "C",
           sol="un(e) Congolais(e) · un(e) Érythréen(ne) · un(e) Guinéen(ne) · un(e) Syrien(ne) · un(e) Ukrainien(ne) · un(e) Afghan(e) · un(e) Marocain(e). Majuscule pour l'habitant (un Belge), minuscule pour l'adjectif (un paysage belge).")
    b.page(f'<h2>Les mots de la population</h2>{e}{e2}{e3}{e4}', "Lexique")

    # ---------- Leçon 1 : décrire un paysage ----------
    l1 = lecon("Décrire un paysage", table(["Pour…", "J'utilise…"], [
        ["situer dans l'image", "<b>au premier plan</b> (devant) · <b>au second plan</b> (au milieu) · <b>à l'arrière-plan</b> (au fond) · <b>à gauche, à droite, au centre</b> · <b>au loin</b>"],
        ["nommer les éléments naturels", "le relief (collines, vallée…), l'eau (rivière, lac…), la végétation (forêt, prairie…), le ciel"],
        ["nommer les éléments humains", "les constructions (maisons, église, pont, usine), les voies de communication (route, chemin de fer), les cultures (champs)"],
        ["dire le type de paysage", "un paysage <b>rural</b> · <b>urbain</b> · <b>littoral</b> (au bord de la mer) · <b>montagnard</b> · <b>industriel</b>"],
        ["varier les verbes", "on voit, on aperçoit · … <b>se trouve</b>, <b>s'étend</b> · la rivière <b>serpente</b>, <b>traverse</b> · la colline <b>domine</b> le village"]], ["44mm", "138mm"]) +
                '<div class="astuce" style="margin:2mm 0 0">✍️ <b>Méthode :</b> je décris <b>du plus proche au plus lointain</b> (ou de gauche à droite), puis je donne le <b>type de paysage</b> et j\'explique <b>comment les hommes l\'utilisent</b> (agriculture, habitat, tourisme…). J\'évite « il y a » à chaque phrase !</div>')
    e = E("J'observe le paysage. J'écris le nom des éléments ① à ⑥ et je dis s'ils sont naturels (N) ou humains (H).", paysage(True, 150) + '<div class="grid3" style="gap:2mm;margin-top:1mm">' + "".join(f'<div class="sm">{"①②③④⑤⑥"[i]} ____________ N / H</div>' for i in range(6)) + '</div>', ["regarde", "ecris"], 1, "B",
          sol="① une forêt (des collines boisées) N — ② une église (un village) H — ③ une rivière N — ④ un pont H — ⑤ une prairie avec des vaches (élevage) N/H : la prairie est naturelle, l'élevage est humain — ⑥ un champ cultivé H")
    p_pay = b.n + 1
    b.page(f'{l1}{e}', "Leçon 1")
    e = E(f"Je complète la description du paysage (p. {p_pay}) avec : à l'arrière-plan · au premier plan · au second plan · serpente · domine · rural.", '<div class="card" style="line-height:2">______________ , une rivière ______________ entre les prairies où paissent des vaches. ______________ , un petit village se trouve sur le versant ; son église ______________ les maisons. À droite, on aperçoit des champs cultivés. ______________ , des collines couvertes de forêts ferment l\'horizon. C\'est un paysage ______________ .</div>', ["complete"], 1, "C",
          sol="Au premier plan · serpente · Au second plan · domine · À l'arrière-plan · rural")
    e2 = E("Je remplace « il y a » par un verbe plus précis : s'étend · se dresse · coule · traverse · borde.", '<p>1. Il y a une forêt sur la colline. → Une forêt ______________ sur la colline.</p><p>2. Il y a une rivière au fond de la vallée. → Une rivière ______________ au fond de la vallée.</p><p>3. Il y a une route qui passe dans le village. → Une route ______________ le village.</p><p>4. Il y a un château sur le rocher. → Un château ______________ sur le rocher.</p><p>5. Il y a des dunes le long de la plage. → Des dunes ______________ la plage.</p>', ["ecris"], 2, "C",
           sol="1. s'étend — 2. coule — 3. traverse — 4. se dresse — 5. bordent")
    e3 = E("J'écoute Mme Lambert décrire un autre paysage. Je coche le type de paysage, puis je dessine-le en 4 éléments.", '<div class="flex" style="gap:5mm"><div style="flex:1">' + "".join(f'<p><span class="chk"></span>{t}</p>' for t in ["paysage rural", "paysage urbain", "paysage littoral", "paysage montagnard"]) + '</div><div class="card" style="flex:2;min-height:36mm;background:#fff"></div></div>', ["ecoute", "coche", "dessine"], 2, "A",
           script="« Au premier plan, on voit une large plage de sable avec quelques parasols. À gauche, une digue bordée d'immeubles s'étend jusqu'au bout de la ville. Au second plan, la mer est calme ; un bateau de pêche rentre au port. À l'arrière-plan, à droite, on aperçoit des dunes et un phare. »",
           sol="Paysage littoral (avec une partie urbaine : la digue et ses immeubles). Dessin : plage, digue avec immeubles, mer avec bateau, dunes et phare.")
    e4 = E("Défi ! Je décris en 5 phrases un paysage de mon pays ou de ma ville (plans, éléments naturels et humains, type de paysage, activités).", lines(5), ["ecris"], 3, "C",
           sol="Production personnelle avec les trois plans, au moins deux verbes précis, le type de paysage et une activité humaine.")
    b.page(f'{e}{e2}{e3}{e4}', "S'entraîner")

    # ---------- Leçon 2 : lire une carte ----------
    l2 = lecon("Lire une carte", '<div class="grid2"><div class="card" style="background:#fff"><b>🗺️ Les éléments d\'une carte</b><p class="sm" style="margin:1mm 0 0">• le <b>titre</b> : de quoi parle la carte ?<br>• la <b>légende</b> : que veulent dire les couleurs et les symboles ?<br>• l\'<b>échelle</b> : 1 cm sur la carte = combien de km en réalité ?<br>• l\'<b>orientation</b> : la flèche du <b>nord</b> (N)<br>• la <b>source</b> et la <b>date</b></p></div>'
                '<div class="card" style="background:#fff"><b>🧭 Les points cardinaux</b><p class="sm" style="margin:1mm 0 0">le <b>nord</b> (N) · le <b>sud</b> (S) · l\'<b>est</b> (E) · l\'<b>ouest</b> (O)<br>et entre les deux : le nord-est (NE), le sud-ouest (SO)…<br><i>Liège se trouve <b>à l\'est de</b> Bruxelles.</i><br><i>Arlon est situé <b>dans le sud</b> du pays.</i><br>⚠️ <b>au</b> nord <b>de</b> (en dehors) ≠ <b>dans le</b> nord <b>de</b> (à l\'intérieur)</p></div></div>'
                '<div class="astuce" style="margin:2mm 0 0">📏 <b>L\'échelle :</b> « 1/1 000 000 » (un millionième) veut dire 1 cm sur la carte = 1 000 000 cm = <b>10 km</b> en réalité. Avec une échelle graphique (une barre), je mesure la barre avec ma latte et je fais une règle de trois. <i>(« latte » = belgicisme pour « règle »)</i></div>')
    e = E("J'observe la carte du relief. Je réponds.", relief("118mm") + f'<p class="sm">1. Quel est le titre de la carte ? {blank("l")} 2. Quelle couleur représente les terres de plus de 200 m ? {blank()}</p><p class="sm">3. Comment s\'appellent les zones A, B et C ? (Basse, Moyenne, Haute Belgique) A : {blank()} B : {blank()} C : {blank()}</p><p class="sm">4. Quel fleuve sépare à peu près la Moyenne et la Haute Belgique ? {blank()} 5. Où se trouve le point culminant ? {blank("l")}</p>', ["regarde", "ecris"], 2, "B",
          sol="1. Le relief de la Belgique (carte simplifiée). — 2. Le brun (orange foncé). — 3. A : Basse Belgique ; B : Moyenne Belgique ; C : Haute Belgique. — 4. La Meuse (avec la Sambre : le sillon Sambre-Meuse). — 5. À Botrange, dans l'est du pays (Hautes Fagnes), près de la frontière allemande.")
    p_map = b.n + 1
    b.page(f'{l2}{e}', "Leçon 2")
    e = E("Je calcule les distances réelles.", '<div class="card sm" style="background:#fff">Ex. : échelle 1 cm = 10 km. Sur la carte, 4,5 cm → 4,5 × 10 = <b>45 km</b>.</div><p>1. Échelle 1 cm = 10 km. Sur la carte, Bruxelles-Namur mesure 5,5 cm. → ______ km</p><p>2. Échelle 1 cm = 25 km. Sur la carte, Ostende-Arlon mesure 10 cm. → ______ km</p><p>3. Échelle 1/500 000 (1 cm = ______ km). Sur la carte, 3 cm → ______ km</p><p>4. La côte belge mesure 67 km. Sur une carte où 1 cm = 10 km, elle mesure ______ cm.</p>', ["ecris"], 2, "C",
          sol="1. 55 km — 2. 250 km (à vol d'oiseau) — 3. 1 cm = 5 km ; 3 cm → 15 km — 4. 6,7 cm")
    e2 = E(f"Les points cardinaux. Je regarde la carte (p. {p_map}) et je complète avec : au nord · à l'est · au sud · à l'ouest · dans le sud · dans le nord.", '<div class="card" style="line-height:2">1. Anvers se trouve ______________ de Bruxelles. 2. Liège se trouve ______________ de Bruxelles. 3. Arlon est situé ______________ du pays. 4. Gand est ______________ de Bruxelles. 5. La France est ______________ de la Belgique. 6. Ostende est ______________ -ouest du pays.</div>', ["complete"], 1, "C",
           sol="1. au nord — 2. à l'est — 3. dans le sud — 4. à l'ouest (au nord-ouest) — 5. au sud — 6. dans le nord(-ouest)")
    e3 = E("J'écoute 5 indices. Sur la carte, je trouve la ville mystère.", '<div class="grid5" style="gap:2mm">' + "".join(f'<div class="card c"><b>{i}</b><br>__________</div>' for i in range(1, 6)) + '</div>', ["ecoute", "ecris"], 2, "A",
           script="1. « Je suis un port sur la mer du Nord, dans le nord-ouest du pays. » — 2. « Je suis la capitale de la Wallonie, au confluent de la Sambre et de la Meuse. » — 3. « Je suis située sur la Meuse, à l'est du pays, près des Pays-Bas et de l'Allemagne. » — 4. « Je suis la ville la plus au sud de la carte, dans la province de Luxembourg. » — 5. « Je suis un grand port sur l'Escaut, au nord de Bruxelles. »",
           sol="1. Ostende — 2. Namur — 3. Liège — 4. Arlon — 5. Anvers")
    e4 = E("Défi ! Je dessine un croquis simple de mon pays (frontières, capitale, un fleuve, une montagne ou un désert) avec un titre, une légende et la flèche du nord.", '<div class="card" style="min-height:62mm;background:#fff"><span class="xs muted">titre :</span></div>', ["dessine", "ecris"], 3, "C",
           sol="Croquis avec titre, légende (au moins 3 éléments), orientation ; capitale correctement placée.")
    b.page(f'{e}{e2}{e3}{e4}', "S'entraîner")

    # ---------- Leçon 3 : la comparaison ----------
    l3 = lecon("Comparer", table(["Je compare…", "Plus +", "Égalité =", "Moins −"], [
        ["un adjectif, un adverbe", "<b>plus</b> grand <b>que</b>", "<b>aussi</b> grand <b>que</b>", "<b>moins</b> grand <b>que</b>"],
        ["un nom", "<b>plus de</b> pluie <b>que</b>", "<b>autant de</b> pluie <b>que</b>", "<b>moins de</b> pluie <b>que</b>"],
        ["un verbe", "il pleut <b>plus que</b>", "il pleut <b>autant que</b>", "il pleut <b>moins que</b>"]], ["44mm", "46mm", "46mm", "46mm"]) +
                '<div class="grid2" style="margin-top:2mm"><div class="card" style="background:#fff"><p class="sm" style="margin:0">🏆 <b>Le superlatif</b> : <b>le plus</b> haut, <b>la moins</b> peuplée, <b>le plus de</b> pluie… <b>de</b> + le groupe.<br><i>Botrange est le point <b>le plus haut de</b> Belgique.</i><br>⚠️ bon → <b>meilleur</b> · bien → <b>mieux</b> · mauvais → <b>pire</b> (ou plus mauvais)</p></div>'
                '<div class="card" style="background:#fff"><p class="sm" style="margin:0">✖️ <b>Combien de fois ?</b> <b>deux fois plus</b> grand que · <b>trois fois moins</b> peuplé que · <b>dix fois plus de</b> pluie que<br>📈 <b>L\'évolution</b> : <b>de plus en plus</b> chaud · <b>de moins en moins</b> d\'habitants<br>➕ <b>Nuancer</b> : <b>beaucoup</b> plus, <b>un peu</b> moins, <b>bien</b> plus, <b>presque aussi</b>…</p></div></div>')
    e = E("Je compare Uccle (Bruxelles) et Kinshasa avec les données. Je complète avec : plus · moins · aussi · autant de · plus de · moins de.", table(["", "Uccle (Bruxelles)", "Kinshasa"], [["Température moyenne en juillet", "19 °C", "23,6 °C"], ["Précipitations en juillet", "77 mm", "1 mm"], ["Précipitations sur l'année", "837 mm", "1 385 mm"]], ["70mm", "56mm", "56mm"]) +
          '<div class="card" style="line-height:2">1. En juillet, il fait ______ chaud à Uccle qu\'à Kinshasa. 2. En juillet, il tombe ______ pluie à Kinshasa qu\'à Uccle. 3. Sur l\'année, Kinshasa reçoit ______ précipitations qu\'Uccle. 4. En janvier, il ne fait pas ______ chaud à Uccle qu\'à Kinshasa ! 5. Il pleut ______ souvent à Uccle en juillet qu\'à Kinshasa.</div>', ["lis", "complete"], 1, "C",
          sol="1. moins — 2. moins de — 3. plus de — 4. aussi — 5. plus (« autant de » ne convient à aucune phrase : piège)")
    e2 = E("Aussi ou autant ? J'entoure.", '<div class="card" style="line-height:2">1. La Flandre est-elle (aussi / autant) grande que la Wallonie ? Non, elle est plus petite. 2. Il y a (aussi / autant) d\'habitants à Liège qu\'à Gand ? 3. Il neige (aussi / autant) en Ardenne qu\'à la côte ? Non, beaucoup plus ! 4. Ce lac est (aussi / autant) profond que la mer du Nord.</div>', ["entoure"], 1, "C",
           sol="1. aussi (+ adjectif) — 2. autant (+ de + nom) — 3. autant (+ verbe) — 4. aussi (+ adjectif)")
    b.page(f'{l3}{e}{e2}', "Leçon 3")
    pays = table(["Pays", "Superficie", "Population (environ)", "Point culminant"], [["Belgique", "30 689 km²", "11,8 millions", "694 m"], ["Pays-Bas", "41 850 km²", "18 millions", "322 m (Vaalserberg)"], ["Luxembourg", "2 586 km²", "680 000", "560 m"], ["RD Congo", "2 345 410 km²", "plus de 100 millions", "5 109 m (mont Stanley)"]], ["40mm", "42mm", "50mm", "50mm"])
    e3 = E("Je lis le tableau et j'écris 4 phrases de comparaison (une avec « … fois plus … »).", pays + '<p class="xs muted">Superficie et sommets : atlas ; population : estimations 2024-2025 arrondies. Le point culminant des Pays-Bas européens est le Vaalserberg.</p>' + lines(3), ["lis", "ecris"], 2, "C",
           sol="Ex. : Les Pays-Bas sont plus grands que la Belgique. Le Luxembourg est beaucoup moins peuplé que la Belgique. La RD Congo est plus de 75 fois plus grande que la Belgique. Le point culminant de la Belgique est plus haut que celui des Pays-Bas.")
    e4 = E("Le superlatif. Avec le tableau, je complète.", '<p>1. Le pays ______________ (grand) du tableau, c\'est ______________ . 2. Le pays ______________ (peuplé), c\'est ______________ . 3. Le pays qui a le point culminant ______________ (haut), ce sont ______________ .</p>', ["ecris"], 2, "C",
           sol="1. le plus grand · la RD Congo — 2. le moins peuplé · le Luxembourg (ou le plus peuplé · la RD Congo) — 3. le moins haut · les Pays-Bas")
    e5 = E("J'écoute 5 affirmations sur les pays du tableau. Vrai ou faux ?", checks(5, ["Vrai", "Faux"]), ["ecoute", "coche"], 2, "A",
           script="1. « La Belgique est plus petite que les Pays-Bas. » — 2. « Le Luxembourg est aussi peuplé que la Belgique. » — 3. « Le point culminant de la RD Congo est presque huit fois plus haut que celui de la Belgique. » — 4. « Les Pays-Bas ont moins d'habitants que la Belgique. » — 5. « Le Luxembourg est le plus petit pays du tableau. »",
           sol="1. Vrai — 2. Faux (beaucoup moins peuplé) — 3. Vrai (5 109 ÷ 694 ≈ 7,4) — 4. Faux (plus d'habitants : 18 millions) — 5. Vrai")
    e6 = E("Meilleur ou mieux ? Je complète.", '<p>1. Pour la randonnée, les chaussures de marche sont ______________ que les baskets. 2. On voit ______________ le paysage du haut de la tour. 3. Le climat de la Hesbaye est ______________ pour l\'agriculture que celui des Fagnes. 4. Avec une carte, on s\'oriente ______________ .</p>', ["ecris"], 1, "C", sol="1. meilleures — 2. mieux — 3. meilleur — 4. mieux")
    e7 = E("Défi ! Je compare mon pays et la Belgique en 4 phrases : superficie, relief, climat, population (avec « deux fois plus », « beaucoup moins »…).", lines(3), ["ecris"], 3, "C",
           sol="Ex. : L'Érythrée est environ quatre fois plus grande que la Belgique, mais elle est beaucoup moins peuplée. Son relief est plus montagneux. Il y fait plus chaud et il pleut moins.")
    b.page(f'{e3}{e4}{e5}{e6}{e7}', "S'entraîner")

    # ---------- Leçon 4 : la proportion ----------
    l4 = lecon("Exprimer une proportion", '<div class="grid2"><div class="card" style="background:#fff"><b>➗ Les fractions et les pourcentages</b><p class="sm" style="margin:1mm 0 0">½ = <b>la moitié</b> = 50 % (cinquante pour cent)<br>⅓ = <b>le tiers</b> ≈ 33 % · ⅔ = <b>les deux tiers</b> ≈ 67 %<br>¼ = <b>le quart</b> = 25 % · ¾ = <b>les trois quarts</b> = 75 %<br>1/10 = <b>un dixième</b> = 10 %<br><b>un sur quatre</b> = 1 élève sur 4 = 25 %</p></div>'
                '<div class="card" style="background:#fff"><b>📊 Dire la quantité</b><p class="sm" style="margin:1mm 0 0"><b>la plupart des</b> habitants <b>vivent</b>… (verbe au pluriel)<br><b>la majorité des</b> élèves <b>vient</b> / <b>viennent</b>… (les deux sont acceptés)<br><b>une minorité de</b>… · <b>une petite partie de</b>…<br>30 % des Belges <b>habitent</b>… (verbe au pluriel)<br>Approximations : <b>environ</b>, <b>près de</b>, <b>presque</b>, <b>plus de</b>, <b>moins de</b>, <b>à peu près</b></p></div></div>'
                '<div class="astuce" style="margin:2mm 0 0">🔢 On écrit <b>30 %</b> avec une espace avant le signe %. En français, la virgule sert de séparateur décimal : <b>2,5 %</b> (deux virgule cinq pour cent). Pour un pourcentage : <b>(partie ÷ total) × 100</b>.</div>')
    e = E("Je relie la fraction, le pourcentage et l'expression.", relie(["½", "¼", "¾", "⅓", "1/10"], ["un dixième (10 %)", "le tiers (environ 33 %)", "la moitié (50 %)", "les trois quarts (75 %)", "le quart (25 %)"]), ["relie"], 1, "B",
          sol="½ → la moitié · ¼ → le quart · ¾ → les trois quarts · ⅓ → le tiers · 1/10 → un dixième")
    e2 = E("J'écris le pourcentage, puis une phrase avec une fraction.", '<div class="card sm" style="background:#fff">Ex. : 10 élèves sur 20 → 50 % → <b>La moitié des élèves</b> prennent le bus.</div><p>1. 5 élèves sur 20 viennent d\'Afrique. → ______ % → ______________________________</p><p>2. 15 élèves sur 20 parlent au moins trois langues. → ______ % → ______________________________</p><p>3. 2 élèves sur 20 sont nés en Belgique. → ______ % → ______________________________</p>', ["ecris"], 2, "C",
           sol="1. 25 % → Un quart des élèves viennent d'Afrique. — 2. 75 % → Les trois quarts des élèves parlent au moins trois langues. — 3. 10 % → Un dixième des élèves sont nés en Belgique.")
    b.page(f'{l4}{e}{e2}', "Leçon 4")
    pies = '<div class="flex" style="justify-content:space-around">' + camembert([("Flandre", 58, "#F2C14E"), ("Wallonie", 31, "#E4572E"), ("Bruxelles", 11, "#4A7BD1")], "Population (2025)") + camembert([("Flandre", 44, "#F2C14E"), ("Wallonie", 55, "#E4572E"), ("Bruxelles", 1, "#4A7BD1")], "Superficie") + '</div><p class="xs muted c">Valeurs arrondies, d\'après Statbel (population au 1<sup>er</sup> janvier 2025). Bruxelles : 161 km², soit environ 0,5 % du territoire.</p>'
    e3 = E("Je lis les deux diagrammes circulaires. Je réponds avec une expression de proportion.", pies + f'<p class="sm">1. Quelle région occupe plus de la moitié du territoire ? {blank("l")}</p><p class="sm">2. Quelle part de la population vit en Wallonie ? (fraction) {blank("l")}</p><p class="sm">3. Où vit la majorité des Belges ? {blank("l")}</p><p class="sm">4. Bruxelles : 11 % de la population sur 1 % du territoire. Qu\'est-ce que cela montre ? {blank("xl")}</p>', ["lis", "ecris"], 2, "B",
           sol="1. La Wallonie (55 %). — 2. Presque un tiers (31 %). — 3. En Flandre (58 %, plus de la moitié). — 4. Que Bruxelles est très densément peuplée : beaucoup d'habitants sur un tout petit territoire (une ville).")
    e4 = E("J'accorde le verbe au présent.", '<p>1. La plupart des élèves (habiter) ______________ près de l\'école. 2. 60 % des Belges (vivre) ______________ en Flandre. 3. La moitié de la classe (partir) ______________ en excursion. 4. La plupart du temps, il (pleuvoir) ______________ en novembre.</p>', ["ecris"], 2, "C",
           sol="1. habitent — 2. vivent — 3. part (accord avec « la moitié » ; « partent » est toléré) — 4. pleut")
    e5 = E("J'écoute les résultats d'une enquête dans une école. J'écris les chiffres.", '<p>1. Élèves qui viennent à l\'école à pied : ______ 2. en bus : ______ 3. en voiture : ______ 4. à vélo : ______ 5. Élèves qui parlent plus de deux langues : ______</p>', ["ecoute", "ecris"], 2, "A",
           script="« Voici les résultats de notre enquête. Sur 400 élèves, la moitié viennent à l'école à pied. Un quart prennent le bus. 15 % viennent en voiture. Les autres, c'est-à-dire 10 %, viennent à vélo. Enfin, près des deux tiers des élèves parlent plus de deux langues ! »",
           sol="1. la moitié (50 %, 200 élèves) — 2. un quart (25 %, 100 élèves) — 3. 15 % (60 élèves) — 4. 10 % (40 élèves) — 5. près des deux tiers (environ 67 %)")
    e6 = E("Défi ! Petite enquête dans la classe : je pose une question à tous (ex. : « Combien de langues parles-tu ? »), puis j'écris 3 phrases avec une fraction ou un pourcentage.", lines(3), ["parle", "ecris", "groupe"], 3, "C",
           sol="Ex. : Sur 16 élèves, 8 parlent arabe : c'est la moitié de la classe. Un élève sur quatre parle aussi anglais. La plupart des élèves parlent au moins trois langues.")
    b.page(f'{e3}{e4}{e5}{e6}', "S'entraîner")

    # ---------- Leçon 5 (FLSco) : lire un climatogramme ----------
    l5 = lecon("Lire un climatogramme", table(["Étape", "Je regarde… / J'écris…"], [
        ["1. Identifier", "le <b>lieu</b> (ville, pays), l'<b>altitude</b>, la <b>période</b> des mesures (ex. 1991-2020)"],
        ["2. Lire les axes", "les <b>barres bleues</b> = les <b>précipitations</b> (en mm, axe de gauche) · la <b>courbe rouge</b> = les <b>températures</b> moyennes (en °C, axe de droite) · en bas : les 12 mois"],
        ["3. Relever", "le mois le plus chaud / le plus froid → l'<b>amplitude thermique</b> = T° max − T° min · le mois le plus / le moins pluvieux · le <b>total</b> des précipitations"],
        ["4. Repérer les saisons", "Y a-t-il une <b>saison sèche</b> ? (mois avec très peu de pluie) · un hiver froid ? un été chaud ?"],
        ["5. Conclure", "« Il s'agit d'un climat… <b>car</b>… » : je <b>justifie</b> avec des chiffres du document."]], ["40mm", "142mm"]) +
                '<div class="astuce" style="margin:2mm 0 0">✍️ Phrases utiles : « Le mois <b>le plus chaud</b> est juillet, avec 19 °C. » · « Les précipitations <b>sont réparties sur toute l\'année</b>. » · « <b>De juin à septembre</b>, il ne pleut presque pas. » · « L\'amplitude thermique <b>est faible / forte</b>. »</div>')
    e = E("Je lis le climatogramme d'Uccle. Je complète.", '<div class="flex top" style="gap:4mm">' + climato(UCCLE_T, UCCLE_P, "Uccle (Bruxelles) · 100 m · 1991-2020", 86) +
          '<div class="sm" style="line-height:1.9">1. Mois le plus chaud : ________ (____ °C)<br>2. Mois le plus froid : ________ (____ °C)<br>3. Amplitude thermique : ____ − ____ = ____ °C<br>4. Mois le plus pluvieux : ________<br>5. Y a-t-il une saison sèche ? ________<br>6. Total : ____ mm par an</div></div>', ["lis", "ecris"], 1, "B",
          sol="1. juillet (19 °C) — 2. janvier (3,7 °C) — 3. 19 − 3,7 = 15,3 °C — 4. décembre (89 mm) — 5. Non : il pleut tous les mois (au moins 45 mm) — 6. 837 mm")
    b.page(f'<span class="tag-doc">🎒 FRANÇAIS DE L\'ÉCOLE</span>{l5}{e}', "Consignes & école")
    e = E("Je lis le climatogramme de Kinshasa (RD Congo). Je réponds par des phrases complètes.", '<div class="flex top" style="gap:4mm">' + climato(KIN_T, KIN_P, "Kinshasa · 1991-2020", 86) +
          f'<div class="sm" style="line-height:1.8">1. Quels sont les mois les plus secs ? {blank("m")}<br>2. Comment appelle-t-on cette période ? {blank("m")}<br>3. Quel est le mois le plus pluvieux ? {blank("m")}<br>4. L\'amplitude thermique est-elle forte ou faible ? Calcule-la. {blank("m")}</div></div>', ["lis", "ecris"], 2, "B",
          sol="1. Juin, juillet et août (7 mm, 1 mm et 4 mm), puis septembre (35 mm). — 2. La saison sèche. — 3. Novembre (255 mm). — 4. Faible : 27,7 − 23,6 = 4,1 °C (il fait chaud toute l'année).")
    e2 = E("Je compare les deux climatogrammes. Je complète le tableau, puis j'écris 3 phrases de comparaison.", table(["", "Uccle", "Kinshasa"], [["Température moyenne annuelle", "", ""], ["Amplitude thermique", "", ""], ["Total des précipitations", "", ""], ["Saison sèche ?", "", ""], ["Type de climat", "", ""]], ["62mm", "60mm", "60mm"]).replace("<td></td>", '<td style="height:7.5mm"></td>') + lines(3), ["lis", "ecris"], 2, "C",
           sol="Uccle : 11 °C · 15,3 °C · 837 mm · non · tempéré océanique — Kinshasa : ≈ 26 °C · 4,1 °C · ≈ 1 385 mm · oui (juin-septembre) · tropical à saison sèche. Ex. : Il fait plus chaud à Kinshasa qu'à Uccle. L'amplitude thermique est presque quatre fois plus forte à Uccle.")
    e3 = E("Les grands types de climat. Je relie.", relie(["le climat tempéré océanique", "le climat tropical", "le climat désertique", "le climat méditerranéen", "le climat polaire"], ["très peu de pluie, très chaud le jour", "étés chauds et secs, hivers doux et pluvieux", "hivers doux, étés frais, pluie toute l'année", "très froid toute l'année", "chaud toute l'année, saison des pluies et saison sèche"]), ["relie"], 1, "B",
           sol="tempéré océanique → hivers doux, étés frais, pluie toute l'année · tropical → chaud toute l'année, saisons des pluies et sèche · désertique → très peu de pluie · méditerranéen → étés chauds et secs · polaire → très froid toute l'année")
    b.page(f'{e}{e2}{e3}', "Consignes & école")
    e = E("Dans les autres cours ! Je reformule les consignes de géographie en mots simples.", '<div class="card sm" style="background:#fff;line-height:1.9">' + G + ' 1. « <b>Localisez</b> Kinshasa sur le planisphère. » &nbsp; 2. « <b>Caractérisez</b> le climat de Bruxelles. »<br>' + G + ' 3. « <b>Justifiez</b> votre réponse <b>à l\'aide du</b> document 2. » &nbsp; 4. « <b>Mettez en relation</b> le relief et la densité de population. »</div>' + lines(4), ["lis", "ecris"], 2, "B",
          sol="1. Trouvez et marquez Kinshasa sur la carte du monde. 2. Décrivez le climat de Bruxelles (températures, pluies, saisons) et donnez son type. 3. Prouvez votre réponse avec des chiffres du document 2. 4. Expliquez le lien entre relief et nombre d'habitants.")
    e2 = E("Je calcule la densité de population (habitants ÷ superficie). J'arrondis à l'unité.", table(["Lieu", "Population", "Superficie", "Densité (hab./km²)"], [["Belgique", "11 825 551", "30 689 km²", ""], ["Luxembourg (pays)", "680 000", "2 586 km²", ""], ["Région de Bruxelles-Capitale", "1 250 000", "161 km²", ""], ["Province de Luxembourg (Belgique)", "300 000", "4 440 km²", ""]], ["66mm", "38mm", "38mm", "40mm"]) + '<p class="sm">Quel lieu est le plus densément peuplé ? Le moins ? Pourquoi, à ton avis ? ' + blank("xl") + '</p>', ["ecris"], 2, "C",
           sol="Belgique ≈ 385 · Luxembourg (pays) ≈ 263 · Bruxelles ≈ 7 764 · province de Luxembourg ≈ 68 (populations arrondies). Le plus dense : Bruxelles (une grande ville) ; le moins dense : la province de Luxembourg (Ardenne : forêts, plateau, climat plus rude, petits villages).")
    e3 = E("Les mots des graphiques. Je complète avec : l'abscisse · l'ordonnée · la légende · l'unité · la source.", '<div class="card" style="line-height:2">1. L\'axe horizontal s\'appelle l\'axe des ______________ . 2. L\'axe vertical s\'appelle l\'axe des ______________ . 3. Les mm et les °C sont ______________ de mesure. 4. ______________ explique les couleurs. 5. ______________ dit d\'où viennent les données.</div>', ["complete"], 1, "C",
           sol="1. abscisses — 2. ordonnées — 3. les unités — 4. La légende — 5. La source")
    b.page(f'{e}{e2}{e3}', "Consignes & école")

    # ---------- Documents de la vie ----------
    met = f'''<div class="doc" style="transform:none;border:2px solid #1F2A44;background:#fff;padding:3mm 4mm;font-size:9.8pt;line-height:1.42">
<div class="flex" style="justify-content:space-between"><b style="font-size:13pt;color:{MC}">☁️ LA MÉTÉO DU COURRIER DE HAUTRIVE</b><span class="xs muted">(journal fictif) · jeudi 12 février</span></div>
<div style="background:#FFE9A8;border-radius:1.5mm;padding:1.5mm 2.5mm;margin:1.5mm 0"><b>⚠️ Avertissement jaune « neige et verglas »</b> pour les provinces de Liège et de Luxembourg, de jeudi 18 h à vendredi 10 h. Prudence sur les routes !</div>
{table(["", "Ciel", "Min.", "Max.", "Vent"], [["🌊 Littoral", "🌤️ éclaircies", "3 °C", "8 °C", "ouest, fort (60 km/h en rafales)"], ["🏙️ Centre (Bruxelles, Namur)", "🌧️ pluie, averses", "2 °C", "6 °C", "ouest, modéré"], ["🌲 Ardenne", "🌨️ neige au-dessus de 400 m", "−3 °C", "1 °C", "faible"]], ["44mm", "44mm", "16mm", "16mm", "52mm"])}
<p style="margin:1.5mm 0 0">📅 <b>Week-end :</b> samedi, temps sec et froid avec du soleil ; dimanche, retour de la pluie par l'ouest. Températures en légère hausse : jusqu'à 9 °C au centre.<br>🌅 Lever du soleil : 8 h 04 · coucher : 17 h 47</p></div>'''
    e = E("Je lis la météo du journal. Je réponds.", met + f'<p class="mt2">1. Quelles provinces sont concernées par l\'avertissement ? Pourquoi ? {blank("xl")}</p><p>2. Où fera-t-il le plus froid jeudi ? Quelle température minimale ? {blank("xl")}</p><p>3. Quelle est la différence de température maximale entre le littoral et l\'Ardenne ? {blank("xl")}</p><p>4. Ta famille veut faire une promenade ce week-end. Quel jour choisir ? Pourquoi ? {blank("xl")}</p><p>5. Combien de temps le soleil reste-t-il levé ce jeudi ? {blank("xl")}</p>', ["lis", "ecris"], 2, "B",
          sol="1. Liège et Luxembourg : neige et verglas. — 2. En Ardenne (−3 °C). — 3. 8 − 1 = 7 °C. — 4. Samedi : sec et ensoleillé. — 5. De 8 h 04 à 17 h 47 : 9 h 43 min.")
    e2 = E("Les mots du bulletin. Je relie.", relie(["le verglas", "une éclaircie", "une averse", "une rafale", "le littoral"], ["une pluie forte et courte", "un coup de vent violent", "une fine couche de glace sur le sol", "la région au bord de la mer", "un moment où le ciel se dégage"]), ["relie"], 1, "B",
           sol="verglas → couche de glace · éclaircie → ciel qui se dégage · averse → pluie forte et courte · rafale → coup de vent violent · littoral → région au bord de la mer")
    b.page(f'<span class="tag-doc">📄 DOCUMENT DE LA VIE</span><h2>La météo du journal</h2>{e}{e2}', "Document de la vie")
    dep = f'''<div class="doc" style="transform:none;border:1.5px solid #9aa1b1;background:#FBFEF8;padding:3mm 4mm;font-size:9.6pt;line-height:1.42">
<div class="flex" style="justify-content:space-between;align-items:flex-start"><div><b style="font-size:13pt;color:#3A7D44">🥾 Parc naturel des Trois Vallées · Promenade n° 7 « Le Rocher du Faucon »</b><br><span class="xs muted">(parc et promenade fictifs)</span></div><div class="xs" style="text-align:right">🚆 départ : gare de Hautrive<br>🅿️ parking gratuit</div></div>
<div class="grid4" style="gap:2mm;margin:1.5mm 0"><div class="card c" style="padding:1mm;background:#fff">📏 <b>12 km</b></div><div class="card c" style="padding:1mm;background:#fff">⏱️ <b>3 h 30</b></div><div class="card c" style="padding:1mm;background:#fff">⛰️ dénivelé : <b>+ 380 m</b></div><div class="card c" style="padding:1mm;background:#fff">🔶 balisage : <b>losange orange</b></div></div>
{profil(170)}
<p style="margin:1mm 0 0">⚠️ Difficulté : moyenne (deux montées raides). Chaussures de marche conseillées ; chemins boueux après la pluie. 🐕 Chiens tenus en laisse. 🔥 Feux interdits. 🚮 Remportez vos déchets. En période de chasse (octobre-décembre), certains chemins peuvent être fermés : consultez les panneaux.</p></div>'''
    e = E("Je lis le dépliant et le profil de la promenade. Je réponds.", dep + f'<p class="mt2">1. Quelle est l\'altitude du départ ? Et du point le plus haut ? Où est-il ? {blank("xl")}</p><p>2. Entre quels kilomètres se trouvent les deux montées les plus raides ? {blank("xl")}</p><p>3. Le moulin se trouve-t-il dans une vallée ou sur un sommet ? Justifie avec le profil. {blank("xl")}</p><p>4. Tu pars à 13 h 30 un 15 décembre. Le soleil se couche vers 16 h 40. Est-ce une bonne idée ? Pourquoi ? {blank("xl")}</p>', ["lis", "ecris"], 2, "B",
          sol="1. 180 m ; 380 m au Rocher du Faucon (km 4). — 2. Km 1 à 3 et km 7 à 9. — 3. Dans une vallée (200 m, point bas entre deux montées). — 4. Non : arrivée vers 17 h, après la tombée de la nuit ; période de chasse.")
    e2 = E("J'écris un message (5 phrases) à un(e) ami(e) pour l'inviter à faire cette promenade : le jour, le lieu de rendez-vous, la difficulté, ce qu'il faut prendre.", lines(5), ["ecris"], 3, "C",
           sol="Ex. : Salut Daria ! Samedi, je fais la promenade du Rocher du Faucon. Tu viens ? Rendez-vous à 10 h à la gare de Hautrive. 12 km et deux montées raides : prends de bonnes chaussures et un pique-nique. À samedi !")
    b.page(f'<span class="tag-doc">📄 DOCUMENT DE LA VIE</span><h2>Le dépliant d\'une promenade</h2>{e}{e2}', "Document de la vie")

    # ---------- Vers les épreuves ----------
    fag = f'''<div class="card" style="{SERIF};background:#F3FAFA;font-size:10pt"><b>Les Hautes Fagnes, un morceau de Grand Nord en Belgique</b> <span class="xs muted">(texte informatif écrit pour la classe)</span>
<p style="margin:1mm 0 0">§1 À l'est de la Belgique, entre Eupen et Malmedy, s'étend un haut plateau battu par les vents : les Hautes Fagnes. On y trouve le point culminant du pays, le signal de Botrange, à 694 mètres d'altitude. Le paysage surprend : peu d'arbres, de grandes étendues d'herbes et de bruyères, et un sol si humide qu'il faut marcher sur des caillebotis.</p>
<p style="margin:1mm 0 0">§2 Ce paysage s'explique par le climat. Les Hautes Fagnes sont la région la plus froide et la plus arrosée de Belgique : il y tombe environ 1 400 mm de précipitations par an, alors qu'Uccle n'en reçoit que 837. L'eau s'écoule mal sur ce sol imperméable. Les plantes mortes ne se décomposent pas complètement : elles s'accumulent et forment la tourbe, au rythme d'environ un millimètre par an.</p>
<p style="margin:1mm 0 0">§3 Ce milieu fragile est protégé : une grande partie du plateau est une réserve naturelle depuis 1957. Certaines zones sont interdites au public, surtout au printemps, quand les oiseaux font leur nid. Pourtant, chaque hiver, quand la neige tombe, des milliers de visiteurs viennent y faire du ski de fond ou de la raquette.</p></div>'''
    e = E("Entraînement de type CE1D : je lis le texte informatif, je réponds et je justifie avec une citation.", fag + f'<p class="sm mt2">a) Vrai ou faux ? Les Hautes Fagnes sont couvertes de forêts. <b>Justifie</b> par une citation. {blank("l")}</p><p class="sm">b) Quelle est l\'idée principale du §2 ? {blank("xl")}</p><p class="sm">c) Combien de précipitations les Hautes Fagnes reçoivent-elles de plus qu\'Uccle ? Montre ton calcul. {blank("l")}</p><p class="sm">d) À ce rythme, combien de temps faut-il pour former un mètre de tourbe ? {blank("l")}</p><p class="sm">e) Relève le connecteur qui marque une opposition dans le §3. Qu\'oppose-t-il ? {blank("xl")}</p>', ["lis", "ecris"], 3, "C",
          sol="a) Faux : « peu d'arbres, de grandes étendues d'herbes et de bruyères ». — b) Le climat explique le paysage et la tourbe. — c) 1 400 − 837 ≈ 563 mm. — d) 1 000 mm → environ 1 000 ans. — e) « Pourtant » : protection ≠ milliers de visiteurs en hiver.")
    e2 = E("Suite de l'épreuve. f) Pourquoi l'auteur parle-t-il d'« un morceau de Grand Nord » dans le titre ? g) Trouve dans le texte un mot de la même famille que « humidité » et un synonyme de « pluvieuse ».", lines(3), ["lis", "ecris"], 3, "C",
           sol="f) Parce que le paysage (peu d'arbres, tourbières, vent, neige) et le climat froid ressemblent à ceux des pays du Nord (Scandinavie). — g) « humide » ; « arrosée ».")
    b.page(EPR.format(k="CE1D", t="Lire un texte informatif et calculer") + e + e2 + '<div class="astuce">💡 En géographie comme en français, je <b>justifie avec le document</b> : une citation entre guillemets ou un chiffre précis, avec son unité (mm, °C, hab./km²).</div>', "Vers les épreuves")
    forum = '''<div class="card" style="background:#fff;font-size:10pt"><b>🗨️ Forum « Jeunes et avenir » · Sujet : Plus tard, vous préférez vivre en ville ou à la campagne ?</b>
<p style="margin:1.5mm 0 0"><b>Lina_17 :</b> La ville, sans hésiter ! Il y a des magasins, des cinémas, les transports en commun… À la campagne, on s'ennuie et il faut toujours une voiture.</p>
<p style="margin:1mm 0 0"><b>Tom.ardennes :</b> Moi, j'habite dans un village près de Bastogne. L'air est pur, c'est calme et les logements sont moins chers. Je ne changerais pour rien au monde !</p></div>'''
    e = E("Entraînement DELF B1 · production écrite (45 minutes, 160 mots minimum).", forum + '<div class="card" style="background:#F3FAFA"><b>Sujet :</b> Vous lisez ce forum. Vous répondez : vous dites où vous préférez vivre et vous justifiez votre choix avec des exemples. Vous comparez la ville et la campagne (au moins deux comparaisons).</div>' +
          '<div class="card sm" style="background:#fff">Plan conseillé : ① je réagis au forum (« Je suis d\'accord avec… ») ② mon choix + argument 1 + exemple ③ argument 2 + exemple ④ ce qui est moins bien (« Bien sûr, … mais… ») ⑤ conclusion.</div>' + lines(12) + table(["Le correcteur regarde si…", "✅"], [[x, '<span class="chk"></span>'] for x in ["je respecte la consigne (forum, choix, justification) et le nombre de mots", "mes idées sont organisées (connecteurs : d'abord, de plus, mais, enfin)", "j'utilise la comparaison (plus… que, moins de… que, autant…)", "mon vocabulaire est varié et mon orthographe est correcte"]], ["160mm", "22mm"]), ["ecris"], 3, "C",
          sol="Texte de 160 mots minimum ; grille DELF B1 (respect de la consigne, cohérence, capacité à argumenter, lexique, morphosyntaxe). Ex. de début : « Bonjour à tous ! Je suis d'accord avec Tom : la campagne est plus calme que la ville… »")
    b.page(EPR.format(k="DELF B1", t="Répondre sur un forum, comparer") + e, "Vers les épreuves")

    # ---------- Sons ----------
    e = E("[o] fermé ou [ɔ] ouvert ? J'écoute et je répète.", '<div class="grid2"><div class="card c"><div class="huge">[o] le plateau</div><p><b>au, eau, ô</b>, <b>o</b> en fin de mot ou devant [z]<br>le plat<b>eau</b> · la c<b>ô</b>te · l\'<b>eau</b> · l\'<b>au</b>tomne · le ch<b>au</b>d · la r<b>o</b>se · le mét<b>ro</b> · le d<b>ô</b>me</p></div><div class="card c"><div class="huge">[ɔ] le nord</div><p><b>o</b> suivi d\'une consonne prononcée<br>le n<b>o</b>rd · le s<b>o</b>l · la r<b>o</b>che · la c<b>o</b>lline · le p<b>o</b>rt · la f<b>o</b>rêt · l\'<b>o</b>rage · le r<b>o</b>cher</p></div></div><p class="sm">⚠️ <b>côte</b> [o] (le bord de la mer, la pente) ≠ <b>cote</b> [ɔ] (une note, un chiffre) · <b>la paume</b> [o] ≠ <b>la pomme</b> [ɔ] · En Belgique, on entend souvent [o] dans « Paul » ou « fausse »… comme en France !</p>', ["ecoute", "repete"], 1, "A",
          script="Lire chaque colonne. Faire sentir la bouche plus fermée et arrondie pour [o] (plateau), plus ouverte pour [ɔ] (nord). Attention : « le rocher » se prononce avec [ɔ].", sol="Activité orale.")
    e2 = E("J'écoute : [o] ou [ɔ] ? Je coche.", checks(8, ["[o]", "[ɔ]"]), ["ecoute", "coche"], 2, "A", script="1. le plateau — 2. le nord — 3. la côte — 4. le port — 5. chaud — 6. la colline — 7. l'eau — 8. l'orage",
           sol="1. [o] — 2. [ɔ] — 3. [o] — 4. [ɔ] — 5. [o] — 6. [ɔ] — 7. [o] — 8. [ɔ]")
    e3 = E("Je lis vite et bien (virelangue).", '<div class="card big c" style="line-height:1.8">Au bord de la côte, au nord du port,<br>l\'orage d\'automne arrose les roches et les roseaux.</div>', ["lis", "parle"], 2, "B", sol="Lecture à voix haute.")
    e4 = E("Côte ou cote ? Paume ou pomme ? Je complète, puis je lis à voix haute.", '<div class="card big" style="line-height:2">1. Nous passons nos vacances sur la ______ belge. 2. Ma ______ en géographie est excellente ! 3. Il tient une ______ rouge dans la ______ de sa main.</div>', ["complete", "lis"], 2, "B", sol="1. côte — 2. cote (belgicisme courant : « note ») — 3. pomme · paume")
    b.page(f'<h2>J\'écoute bien · [o] et [ɔ]</h2>{e}{e2}{e3}{e4}', "Sons")
    e = E("Lire les chiffres de la géographie. J'écoute et je répète.", table(["On écrit…", "On lit…"], [["30 689 km²", "trente mille six cent quatre-vingt-neuf kilomètres carrés"], ["385 hab./km²", "trois cent quatre-vingt-cinq habitants au kilomètre carré"], ["11,8 millions", "onze virgule huit millions (onze millions huit cent mille)"], ["837 mm", "huit cent trente-sept millimètres"], ["−3 °C", "moins trois degrés"], ["25 %", "vingt-cinq pour cent"], ["¾", "les trois quarts"], ["1/500 000", "un cinq cent millième"]], ["44mm", "138mm"]), ["ecoute", "repete"], 1, "A",
          script="Lire chaque ligne ; faire répéter. Rappeler : en Belgique, on dit « quatre-vingt-neuf » (comme en France) mais « septante » et « nonante » ; « km² » se lit « kilomètres carrés » ; « hab./km² » se lit « habitants au (ou par) kilomètre carré ».", sol="Activité orale.")
    e2 = E("Dictée de chiffres. J'écoute et j'écris en chiffres avec l'unité.", '<p>1. ______________ 2. ______________ 3. ______________ 4. ______________ 5. ______________</p>', ["ecoute", "ecris"], 2, "A",
           script="1. Six cent nonante-quatre mètres. — 2. Mille trois cent quatre-vingt-cinq millimètres. — 3. Moins cinq degrés. — 4. Septante-cinq pour cent. — 5. Deux millions trois cent quarante-cinq mille quatre cent dix kilomètres carrés.",
           sol="1. 694 m — 2. 1 385 mm — 3. −5 °C — 4. 75 % — 5. 2 345 410 km²")
    e3 = E("En duo : je présente le climat d'Uccle ou de Kinshasa à mon voisin en 4 phrases, sans regarder mon livre. Il vérifie les chiffres sur le climatogramme.", chk3(["J'ai dit les chiffres avec la bonne unité (degrés, millimètres).", "J'ai utilisé « le plus… », « le moins… ».", "Mon voisin a compris toutes mes phrases."]), ["parle", "duo", "coche"], 2, "A", sol="Présentation orale ; évaluation entre pairs.")
    e4 = E("Je lis à voix haute les phrases. Attention aux nombres et aux unités !", '<div class="card" style="line-height:1.8">La RD Congo mesure 2 345 410 km² : elle est environ 76 fois plus grande que la Belgique.<br>À Kinshasa, il tombe 255 mm de pluie en novembre et seulement 1 mm en juillet.<br>Près de 58 % des Belges vivent en Flandre, sur 44 % du territoire.</div>', ["lis", "parle"], 2, "B", sol="Lecture à voix haute : deux millions trois cent quarante-cinq mille quatre cent dix kilomètres carrés ; septante-six ; deux cent cinquante-cinq millimètres ; un millimètre ; cinquante-huit pour cent ; quarante-quatre pour cent.")
    b.page(f'<h2>J\'écoute bien · lire les chiffres de la géographie</h2>{e}{e2}{e3}{e4}', "Sons")

    # ---------- Révision spirale ----------
    e = E("🔁 V3 · Module 4 · Le plus-que-parfait. Je conjugue.", '<p>Quand nous sommes arrivés au sommet, le brouillard (se lever) ______________ . Les élèves étaient fatigués parce qu\'ils (marcher) ______________ trois heures.</p>', ["complete"], 1, "C", sol="s'était levé · avaient marché")
    e2 = E("🔁 V3 · Module 4 · Les siècles. J'écris en chiffres romains.", '<p>La réserve des Hautes Fagnes a été créée en 1957, au ______ siècle. Nous vivons au ______ siècle.</p>', ["ecris"], 1, "C", sol="XXe · XXIe")
    e3 = E("🔁 V3 · Module 3 · La cause et la conséquence. Je complète avec : car · donc · à cause du · grâce au.", '<p>Le sol est imperméable, ______ l\'eau reste en surface. La tourbe se forme ______ froid et de l\'humidité. Les terres de Hesbaye sont fertiles ______ limon. Il faut des bottes ______ le sol est gorgé d\'eau.</p>', ["complete"], 1, "C", sol="donc · à cause du · grâce au · car")
    e4 = E("🔁 V3 · Module 2 · Les phrases conditionnelles. Je complète.", '<p>S\'il (neiger) ______________ demain, nous ferons du ski de fond. Si nous avions une carte, nous (trouver) ______________ le chemin plus facilement.</p>', ["complete"], 2, "C", sol="neige · trouverions")
    e5 = E("🔁 V3 · Module 1 · Les verbes des consignes. Que dois-tu faire si on te demande de « justifier » ? Et de « localiser » ?", lines(2), ["ecris"], 1, "C", sol="Justifier : expliquer pourquoi, avec des preuves (une citation, un chiffre). Localiser : dire ou montrer où se trouve un lieu.")
    e6 = E("🔁 V2 · Module 6 · La Belgique. Je complète : Namur · trois · Bruxelles · la mer du Nord.", '<p>La Belgique a ______ régions. La capitale du pays est ______ ; celle de la Wallonie est ______ . Le pays a une côte sur ______ .</p>', ["complete"], 1, "C", sol="trois · Bruxelles · Namur · la mer du Nord")
    e7 = E("🔁 V2 · Module 7 · Le futur simple. Je mets les verbes au futur (bulletin météo).", '<p>Demain, il (faire) ______________ froid. Le vent (souffler) ______________ fort et la neige (tomber) ______________ en Ardenne. Nous (pouvoir) ______________ faire de la luge !</p>', ["complete"], 2, "C", sol="fera · soufflera · tombera · pourrons")
    b.page(f'<h2>🔁 Je révise les modules précédents</h2>{e}{e2}{e3}{e4}{e5}{e6}{e7}', "Je révise")

    # ---------- Ateliers ----------
    e = E("Le podcast « Planète curieuse » : Kinshasa et Brazzaville. J'écoute deux fois et je complète la fiche.", table(["", "Mes notes"], [["🌍 Où se trouvent les deux villes ?", ""], ["🌊 Qu'est-ce qui les sépare ?", ""], ["🏛️ De quels pays sont-elles les capitales ?", ""], ["👥 Combien d'habitants à Kinshasa ?", ""], ["☔ Quand pleut-il le plus ? le moins ?", ""], ["⚖️ Une comparaison avec Bruxelles", ""]], ["80mm", "102mm"]).replace("<td></td>", '<td style="height:10mm"></td>'), ["ecoute", "ecris"], 2, "A",
          script="« Bienvenue dans Planète curieuse ! Aujourd'hui, nous partons en Afrique centrale. Sur les deux rives du fleuve Congo, deux capitales se regardent : Kinshasa, capitale de la République démocratique du Congo, et Brazzaville, capitale de la République du Congo. Ce sont les deux capitales les plus proches du monde, si on ne compte pas Rome et le Vatican. Kinshasa est une ville immense : selon les estimations, elle compte plus de 15 millions d'habitants, soit plus que toute la Belgique ! Le climat y est tropical : il fait chaud toute l'année. Les pluies les plus fortes tombent en novembre ; de juin à septembre, c'est la saison sèche, un peu plus fraîche. Il tombe environ 1 400 millimètres de pluie par an, beaucoup plus qu'à Bruxelles. »",
          sol="Afrique centrale, face à face · le fleuve Congo · RD Congo / République du Congo · plus de 15 millions (estimations) · le plus en novembre ; saison sèche de juin à septembre · ex. : Kinshasa a plus d'habitants que toute la Belgique.")
    e2 = E("En duo : je joue le présentateur ou la présentatrice météo. Je présente en 1 minute la météo de demain en Belgique (côte, centre, Ardenne) avec le futur et 2 comparaisons. Mon voisin m'évalue.", chk3(["Il / elle a parlé des trois régions.", "Il / elle a utilisé le futur et 2 comparaisons (plus froid que…).", "Il / elle a parlé clairement, en regardant le public."]), ["parle", "duo", "coche"], 2, "A", sol="Évaluation entre pairs.")
    e3 = E("Je prépare 3 questions sur le podcast pour un camarade (Où… ? Combien… ? Quand… ?), puis je lui pose mes questions.", lines(3), ["ecris", "parle", "duo"], 1, "A", sol="Ex. : Où se trouve Kinshasa ? Combien d'habitants compte-t-elle ? Quand est la saison sèche ?")
    b.page(f'{atl_head("A", "Atelier · Le podcast de géographie")}{e}{e2}{e3}', "Atelier")
    let = f'''<div class="card" style="{SERIF};background:#FBF6EC;font-size:10.1pt;border:1.5px solid #c9b48a">{G} <span class="xs muted">(courriel fictif écrit pour la classe)</span>
<p style="margin:1mm 0 0"><b>De :</b> Ruth · <b>À :</b> Fatou · <b>Objet :</b> Ici, c'est la saison sèche !</p>
<p style="margin:1mm 0 0">Coucou ma cousine !</p>
<p style="margin:1mm 0 0">Merci pour ta photo de la neige dans les Fagnes : toute la famille l'a regardée ! Ici, à Kinshasa, nous sommes en juillet, en pleine saison sèche. Il ne pleut presque jamais et le ciel est souvent gris ; on dit que c'est la saison « fraîche », mais il fait quand même 24 degrés en moyenne. Pour toi, ce serait l'été !</p>
<p style="margin:1mm 0 0">En novembre, c'est tout le contraire : les orages sont si violents que certaines rues se transforment en rivières. Papa dit qu'il pleut parfois plus en une nuit qu'en un mois à Bruxelles. La ville grandit tellement vite qu'on construit partout, même sur les collines, et la terre glisse quand il pleut.</p>
<p style="margin:1mm 0 0">Le week-end dernier, nous sommes allés au bord du fleuve. De l'autre côté, on voyait Brazzaville, une autre capitale, dans un autre pays ! Raconte-moi ta classe de dépaysement. Est-ce que tu as eu aussi froid que moi en saison sèche ? 😉</p>
<p style="margin:1mm 0 0;text-align:right">Gros bisous, Ruth</p></div>'''
    e = E("Je lis le courriel de Ruth. Je réponds.", let + f'<p class="mt2">1. Qui écrit à qui ? Où vit Ruth ? {blank("xl")}</p><p>2. Comment est le temps à Kinshasa en juillet ? (2 éléments) {blank("xl")}</p><p>3. Que se passe-t-il en novembre ? Vérifie avec le climatogramme de Kinshasa. {blank("xl")}</p><p>4. Pourquoi la terre glisse-t-elle sur les collines ? {blank("xl")}</p><p>5. Pourquoi Ruth met-elle un 😉 à la fin de sa question ? {blank("xl")}</p>', ["lis", "ecris"], 2, "B",
          sol="1. Ruth, à sa cousine Fatou ; Ruth vit à Kinshasa. — 2. Presque pas de pluie, ciel gris, environ 24 °C. — 3. De violents orages ; oui, novembre est le mois le plus pluvieux (255 mm). — 4. On construit partout, même sur les collines, et la pluie est très forte. — 5. Humour : 24 °C n'est pas froid pour Fatou.")
    e2 = E("Comparer : dans le courriel, relève deux comparaisons. Puis écris la réponse de Fatou à Ruth (5 phrases) avec 2 comparaisons entre la Belgique et Kinshasa.", lines(6), ["ecris"], 3, "C",
           sol="« il pleut parfois plus en une nuit qu'en un mois à Bruxelles » ; « aussi froid que moi ». Réponse : ex. Chère Ruth, ici il fait beaucoup plus froid qu'à Kinshasa : dans les Fagnes, il faisait −2 °C ! Il pleut moins fort, mais plus souvent…")
    b.page(f'{atl_head("B", "Atelier · Un courriel de Kinshasa")}{e}{e2}', "Atelier")
    e = E("J'écris une carte postale « paysage » : je décris un lieu que j'aime (dans mon pays ou en Belgique) pour un(e) ami(e) (environ 120 mots).", '<div class="card sm" style="background:#fff">Plan : <b>formule d\'appel</b> · <b>où je suis</b> (localiser : dans le nord de…, près de…) · <b>le paysage</b> (au premier plan, au loin… ; éléments naturels et humains ; verbes précis) · <b>le temps et le climat</b> · <b>une comparaison</b> avec ta ville · <b>formule finale</b>. Au recto, je dessine le paysage.</div>' +
          '<div class="grid2" style="grid-template-columns:1fr 1fr;gap:3mm"><div class="card" style="min-height:100mm;background:#fff"><span class="xs muted">recto : mon dessin</span></div><div>' + lines(11) + '</div></div>', ["ecris", "dessine"], 2, "C",
          sol="Carte d'environ 120 mots : localisation, description en plans, deux verbes précis, temps / climat, au moins une comparaison, formules d'appel et finale.")
    e2 = E("Je relis la carte postale de mon voisin avec la grille et je lui donne un conseil.", chk3(["Le lieu est bien localisé (nord, sud, près de…).", "Le paysage est décrit en plans, avec des verbes précis.", "Il y a au moins une comparaison."]), ["lis", "duo", "coche"], 1, "C", sol="Relecture entre pairs.")
    b.page(f'{atl_head("C", "Atelier · La carte postale")}{e}{e2}', "Atelier")
    cards = [("Je suis le plus grand pays du monde. Mes hivers sont très froids.", "la Russie"), ("Le Nil me traverse du sud au nord. La plus grande partie de mon territoire est un désert.", "l'Égypte"), ("Le plus haut sommet du monde, l'Everest, est à ma frontière avec la Chine.", "le Népal"), ("Une grande partie de mon territoire est sous le niveau de la mer. Je suis le voisin de la Belgique.", "les Pays-Bas"),
             ("La plus grande partie de la forêt amazonienne est sur mon territoire.", "le Brésil"), ("Je suis le pays le plus peuplé du monde depuis 2023.", "l'Inde"), ("Je suis formé de milliers d'îles. Les tremblements de terre y sont fréquents.", "le Japon"), ("Je suis très long et très étroit, entre l'océan Pacifique et la cordillère des Andes.", "le Chili"),
             ("Je suis à la fois un pays et un continent, entouré par les océans.", "l'Australie"), ("Mes montagnes, l'Atlas, séparent la côte et le Sahara.", "le Maroc"), ("Je suis le deuxième plus grand pays du monde. Je parle anglais et français.", "le Canada"), ("Je suis traversé par le fleuve Congo et je suis plus de 75 fois plus grand que la Belgique.", "la RD Congo")]
